head.script:
// 화면 리사이징

scwin.gExplDisclsAcptNo;
scwin.gIsurCd;
scwin.gExplList;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '6') {
        // 코넥스 시장 추가 20130520 LDJ
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        panel_mkt.hide();
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '6') {
            $c.cm.setColumnProp(grd_Grid, "BFDECSN_DISCLS_CNT", "Show", false); // 미확정횟수는 코스닥만 20171215

        }
    }
    cmb_fix.setValue(0);

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 3)); // 3년전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 유가일때만 초기 검색함
    if (js_market === '1') {
        fn_CheckCond();
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !조회공시--;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    scwin.gDepCd = cmb_TeamList.getValue();
    scwin.gEmpNo = cmb_EmpList.getValue();
    fn_Search();
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !조회공시--;
클릭-- > function() {
    const url_list = "/ExplanationDisclosure.do?method=listExplanationDscl&inputMessageId=EXPLDISCLSCOND_IN" + "&outputMessageId=EXPLDISCLSLIST_OUT";
    const url_cond = "&ISUR_NM_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + js_belngdepcd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + rdo_MKT_ID.getValue() + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&FINAL_YN=" + cmb_fix.getValue() + "&RUMR_NEWS_CONTN=" + txb_contn.getValue() + "&SCREN_ID=" + 'ULDSTF30220.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_ExplDsclList.DataID = encodeURI(url_list + url_cond);
    dts_ExplDsclList.reset();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gExplDisclsAcptNo = dts_ExplDsclList.getCellData(Number(obj), "EXPLDISCLS_ACPT_NO");
    scwin.gIsurCd = dts_ExplDsclList.getCellData(Number(obj), "ISUR_CD");
    scwin.gExplList = dts_ExplDsclList.getCellData(Number(obj), "EXPL_LIST");
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DISCLS_TITLE") {
        await $c.stf.openDisclViewer(scwin.gExplDisclsAcptNo, 'R');
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "EXPL_LIST") {
        // var url = "/dsclmgt/ULDSTF30221.gfm";
        // var winTitle ="해명공시 목록";
        if (scwin.gExplList === "-") {
            // frame.CreateFrame("EXPL_LIST"+gExplDisclsAcptNo, url , winTitle ,200, 100, 920, 600+30, "window" , 0, 0, true);

        } else {
            // frame.CreateFrame("EXPL_LIST"+gExplDisclsAcptNo, url , winTitle ,200, 50, 1000, 700+30, "window" , 0, 0, true);
            // frame.CreateFrame("EXPL_LIST"+gExplDisclsAcptNo, url , winTitle ,200, 50, 1000, 700+30, "window" , 0, 0, true);
            const options = {
                id: "ULDSTF30221",
                title: "해명공시 목록",
                type: "browserPopup",
                width: "700px",
                height: "500px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dsclmgt/ULDSTF30221.gfm", options);
        }
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name dts_ExplDsclList_OnLoadError
 * @description dts_ExplDsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ExplDsclList_OnLoadError = async function() {
    await $c.win.alert(dts_ExplDsclList);
};

/**
 * @method
 * @name dts_ExplDsclList_OnLoadCompleted
 * @description dts_ExplDsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ExplDsclList_OnLoadCompleted = async function(rowcount) {
    if (dts_ExplDsclList.errorMsg) {
        await $c.win.alert(dts_ExplDsclList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name dts_emp_OnLoadError
 * @description dts_emp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_emp_OnLoadError = async function() {
    await $c.win.alert(dts_emp);
};

/**
 * @method
 * @name dts_dep_OnLoadError
 * @description dts_dep 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_dep_OnLoadError = async function() {
    await $c.win.alert(dts_dep);
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description 유가일때만 디폴트 로그인한 사용자
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자
    if (js_market === '1') {
        cmb_TeamList.setValue(js_dep_cd);
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description 유가일때만 디폴트 로그인한 사용자
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자
    if (js_market === '1') {
        cmb_EmpList.setValue(js_emp_no);
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd === '') {
        cmb_EmpList.setValue('');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    // dts_emp.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description 부서코드에  해당하는 사원을 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF30220.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "조회공시요구 목록", type: "2"});
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name txb_contn_onkeydown
 * @description txb_contn 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_contn_onkeydown = function() {
    if (window.event.keyCode === "13") {
        fn_CheckCond();
    }
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    await scwin.setCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
